-- FluxyChat D1 baseline schema (migration 0136)
-- Generated by scripts/export-d1-baseline.mjs — schema only, no seed data.
-- Apply on empty DBs only; existing environments should use incremental migrations.
-- Regenerate after adding migrations: pnpm run db:export-baseline

CREATE TABLE activity_events (
  id TEXT PRIMARY KEY,
  feed_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  event_type TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  actor_name TEXT,
  entity_type TEXT,
  entity_id TEXT,
  entity_name TEXT,
  action TEXT NOT NULL,
  metadata TEXT NOT NULL DEFAULT '{}',
  timestamp TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (feed_id) REFERENCES activity_feeds(id)
);

CREATE TABLE activity_feeds (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  feed_type TEXT NOT NULL DEFAULT 'project',
  room_id TEXT,
  description TEXT,
  is_public INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE admin_totp_backup_codes (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  code_hash TEXT NOT NULL,
  used_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE admin_totp_secrets (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  secret TEXT NOT NULL,
  algorithm TEXT NOT NULL DEFAULT 'SHA1',
  digits INTEGER NOT NULL DEFAULT 6,
  period INTEGER NOT NULL DEFAULT 30,
  enabled INTEGER NOT NULL DEFAULT 0,
  verified_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE(project_id, user_id)
);

CREATE TABLE agent_capacity (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  max_concurrent INTEGER NOT NULL DEFAULT 5,
  current_load INTEGER NOT NULL DEFAULT 0,
  capabilities TEXT,                    
  is_available INTEGER NOT NULL DEFAULT 1,
  round_robin_index INTEGER NOT NULL DEFAULT 0,
  last_assigned_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(project_id, user_id)
);

CREATE TABLE agent_marketplace (
  id TEXT PRIMARY KEY,
  publisher_id TEXT NOT NULL,
  name TEXT NOT NULL,
  slug TEXT NOT NULL,
  description TEXT,
  long_description TEXT,
  category TEXT NOT NULL DEFAULT 'general',
  icon_url TEXT,
  config_template TEXT NOT NULL,
  system_prompt TEXT,
  tools TEXT,
  integrations TEXT,
  pricing TEXT DEFAULT 'free',
  pricing_config TEXT,
  version TEXT NOT NULL DEFAULT '1.0.0',
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'review', 'published', 'rejected', 'archived')),
  install_count INTEGER NOT NULL DEFAULT 0,
  avg_rating REAL NOT NULL DEFAULT 0,
  review_count INTEGER NOT NULL DEFAULT 0,
  featured INTEGER NOT NULL DEFAULT 0,
  tags TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE agent_marketplace_installs (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  installed_by TEXT NOT NULL,
  config_override TEXT,
  enabled INTEGER NOT NULL DEFAULT 1,
  installed_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE agent_marketplace_reviews (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  rating INTEGER NOT NULL CHECK (rating >= 1 AND rating <= 5),
  title TEXT,
  body TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE agent_profiles (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  
  tone TEXT NOT NULL DEFAULT 'professional'
    CHECK(tone IN ('professional', 'friendly', 'formal', 'casual', 'empathetic', 'technical')),
  verbosity TEXT NOT NULL DEFAULT 'balanced'
    CHECK(verbosity IN ('concise', 'balanced', 'detailed')),
  
  follow_up_style TEXT NOT NULL DEFAULT 'proactive'
    CHECK(follow_up_style IN ('proactive', 'reactive', 'minimal')),
  escalation_threshold TEXT NOT NULL DEFAULT 'medium'
    CHECK(escalation_threshold IN ('low', 'medium', 'high', 'never')),
  
  policy_constraints TEXT,  
  
  business_objectives TEXT, 
  
  system_prompt_addendum TEXT, 
  
  ab_test_weight INTEGER NOT NULL DEFAULT 100, 
  
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(project_id, name)
);

CREATE TABLE agent_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  room_id TEXT,
  status TEXT NOT NULL, 
  latency_ms INTEGER,
  input_tokens INTEGER DEFAULT 0,
  output_tokens INTEGER DEFAULT 0,
  estimated_cost REAL DEFAULT 0,
  error TEXT,
  created_at TEXT NOT NULL
, tool_calls_json TEXT, context_fetched INTEGER DEFAULT 0, iterations INTEGER DEFAULT 1);

CREATE TABLE agent_tasks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'open',
  priority INTEGER NOT NULL DEFAULT 0,
  assignee_user_id TEXT,
  claimed_at TEXT,
  sla_due_at TEXT NOT NULL,
  resolved_at TEXT,
  disposition TEXT,
  note TEXT,
  trigger_source TEXT NOT NULL DEFAULT 'manual',
  created_by_user_id TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE ai_action_executions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  action_id TEXT NOT NULL,
  room_id TEXT,
  user_id TEXT,
  input TEXT,   
  output TEXT,  
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'success', 'failed')),
  error TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE ai_action_policies (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  action_type TEXT NOT NULL,
  tool_name TEXT,
  allowed INTEGER NOT NULL DEFAULT 1,
  require_approval INTEGER NOT NULL DEFAULT 0,
  max_executions_per_hour INTEGER,
  allowed_user_roles TEXT NOT NULL DEFAULT '["owner","admin"]',
  conditions TEXT NOT NULL DEFAULT '{}',
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE ai_actions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  kind TEXT NOT NULL CHECK(kind IN ('webhook', 'email', 'ticket', 'github_issue', 'custom')),
  config TEXT NOT NULL,  
  enabled INTEGER DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE ai_analytics_insights (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  insight_type TEXT NOT NULL CHECK (insight_type IN ('engagement', 'activity', 'performance', 'retention', 'content', 'agent', 'custom')),
  title TEXT NOT NULL,
  summary TEXT NOT NULL,
  data TEXT DEFAULT '{}',
  period_start TEXT,
  period_end TEXT,
  model TEXT,
  confidence REAL DEFAULT 0,
  generated_at TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at TEXT
);

CREATE TABLE ai_companion_interactions (
  id TEXT PRIMARY KEY,
  companion_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  user_id TEXT,
  input_text TEXT NOT NULL,
  output_text TEXT NOT NULL,
  tokens_used INTEGER,
  latency_ms INTEGER,
  triggered_by TEXT CHECK (triggered_by IN ('mention', 'keyword', 'schedule', 'always', 'manual')),
  created_at TEXT NOT NULL
);

CREATE TABLE ai_companion_memory (
  id TEXT PRIMARY KEY,
  companion_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  room_id TEXT,
  memory_type TEXT NOT NULL DEFAULT 'conversation' CHECK (memory_type IN ('conversation', 'fact', 'preference', 'summary', 'instruction')),
  content TEXT NOT NULL,
  source TEXT,
  importance REAL DEFAULT 0.5,
  expires_at TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE ai_companion_rooms (
  id TEXT PRIMARY KEY,
  companion_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1,
  join_message TEXT,
  leave_message TEXT,
  custom_prompt_override TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE ai_companions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  avatar_url TEXT,
  description TEXT,
  system_prompt TEXT NOT NULL,
  personality TEXT,
  skills TEXT,
  trigger_mode TEXT NOT NULL DEFAULT 'mention' CHECK (trigger_mode IN ('mention', 'keyword', 'always', 'schedule', 'silent')),
  trigger_keywords TEXT,
  temperature REAL DEFAULT 0.7,
  max_tokens INTEGER DEFAULT 1024,
  model TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'archived')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE ai_image_generations (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  message_id TEXT,
  user_id TEXT NOT NULL,
  prompt TEXT NOT NULL,
  revised_prompt TEXT,
  image_url TEXT,
  image_r2_key TEXT,
  image_size TEXT DEFAULT '1024x1024',
  image_quality TEXT DEFAULT 'standard',
  image_style TEXT DEFAULT 'vivid',
  model TEXT DEFAULT 'dall-e-3',
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'generating', 'completed', 'failed')),
  error TEXT,
  tokens_used INTEGER DEFAULT 0,
  processing_time_ms INTEGER,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  completed_at TEXT
);

CREATE TABLE ai_moderation_queue (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  message_id INTEGER,
  user_id TEXT NOT NULL,
  content TEXT,                          
  severity TEXT NOT NULL CHECK(severity IN ('none', 'low', 'medium', 'high', 'critical')),
  categories TEXT,                       
  reason TEXT,                           
  confidence REAL DEFAULT 0.8,
  suggested_action TEXT NOT NULL CHECK(suggested_action IN ('none', 'log', 'flag', 'warn', 'delete', 'mute', 'ban')),
  auto_action_taken TEXT,               
  reviewed_by TEXT,                     
  reviewed_at TEXT,
  review_action TEXT,                   
  review_notes TEXT,
  source_message_id INTEGER,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE ai_policy_violations (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  policy_id TEXT NOT NULL,
  action_id TEXT,
  agent_id TEXT,
  user_id TEXT,
  violation_type TEXT NOT NULL,
  details TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (policy_id) REFERENCES ai_action_policies(id)
);

CREATE TABLE ai_room_configs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  agent_type TEXT NOT NULL DEFAULT 'support',
  agent_name TEXT NOT NULL DEFAULT 'AI Assistant',
  agent_avatar_url TEXT,
  agent_system_prompt TEXT,
  agent_model TEXT DEFAULT 'gpt-4o-mini',
  welcome_message TEXT,
  response_style TEXT DEFAULT 'professional',
  allowed_topics TEXT NOT NULL DEFAULT '[]',
  escalation_threshold REAL DEFAULT 0.7,
  auto_resolve_minutes INTEGER DEFAULT 30,
  embed_enabled INTEGER NOT NULL DEFAULT 1,
  embed_position TEXT DEFAULT 'bottom-right',
  embed_color TEXT DEFAULT '#0066ff',
  embed_title TEXT DEFAULT 'Chat with us',
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE analytics_queries (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  query_text TEXT NOT NULL,
  parsed_intent TEXT NOT NULL DEFAULT '{}',
  query_result TEXT NOT NULL DEFAULT '{}',
  response_text TEXT,
  execution_time_ms INTEGER,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE analytics_query_cache (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  query_hash TEXT NOT NULL,
  result TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE anti_spam_rules (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  rule_name TEXT NOT NULL,
  rule_type TEXT NOT NULL,
  config TEXT NOT NULL DEFAULT '{}',
  action TEXT NOT NULL DEFAULT 'warn',
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE api_keys (
  id TEXT PRIMARY KEY, 
  project_id TEXT NOT NULL,
  secret TEXT NOT NULL, 
  created_at TEXT NOT NULL, key_prefix TEXT, key_hash TEXT, revoked_at TEXT,
  FOREIGN KEY (project_id) REFERENCES projects(id)
);

CREATE TABLE approval_requests (
  id TEXT PRIMARY KEY,
  workflow_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  requester_id TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  context_type TEXT,
  context_id TEXT,
  context_data TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'pending',
  decision TEXT,
  decided_by TEXT,
  decided_at TEXT,
  sla_due_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (workflow_id) REFERENCES approval_workflows(id)
);

CREATE TABLE approval_votes (
  id TEXT PRIMARY KEY,
  request_id TEXT NOT NULL,
  voter_id TEXT NOT NULL,
  vote TEXT NOT NULL,
  comment TEXT,
  voted_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (request_id) REFERENCES approval_requests(id)
);

CREATE TABLE approval_workflows (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  workflow_type TEXT NOT NULL DEFAULT 'single',
  required_approvals INTEGER NOT NULL DEFAULT 1,
  required_roles TEXT NOT NULL DEFAULT '["owner","admin"]',
  sla_minutes INTEGER DEFAULT 60,
  auto_approve_after_sla INTEGER NOT NULL DEFAULT 0,
  notify_on_request INTEGER NOT NULL DEFAULT 1,
  notify_on_decision INTEGER NOT NULL DEFAULT 1,
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE attachments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  message_id INTEGER,
  kind TEXT NOT NULL,
  url TEXT NOT NULL,
  name TEXT NOT NULL,
  size_bytes INTEGER,
  content_type TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE auction_bids (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id TEXT NOT NULL,
  lot_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  amount REAL NOT NULL,
  is_winning INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);

CREATE TABLE auction_lots (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  starting_price REAL NOT NULL DEFAULT 0,
  current_price REAL NOT NULL DEFAULT 0,
  reserve_price REAL,
  bid_increment REAL NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'extended', 'sold', 'unsold')),
  winner_id TEXT,
  start_at TEXT,
  end_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE auction_watchers (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  lot_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  created_at TEXT NOT NULL
);

CREATE TABLE audit_export_runs (
  id TEXT PRIMARY KEY,
  schedule_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  event_count INTEGER NOT NULL DEFAULT 0,
  error TEXT,
  started_at TEXT NOT NULL,
  completed_at TEXT
);

CREATE TABLE audit_export_schedules (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  frequency TEXT NOT NULL CHECK (frequency IN ('daily', 'weekly', 'monthly')),
  format TEXT NOT NULL DEFAULT 'json',
  filter_actor TEXT,
  filter_action TEXT,
  filter_resource TEXT,
  filter_severity TEXT,
  destination_type TEXT NOT NULL CHECK (destination_type IN ('webhook', 'siem', 'email')),
  destination_url TEXT,
  destination_config TEXT,
  enabled INTEGER NOT NULL DEFAULT 1,
  last_run_at TEXT,
  next_run_at TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE automation_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  event_type TEXT NOT NULL,
  room_id TEXT,
  payload TEXT,
  delivered INTEGER DEFAULT 0,
  created_at TEXT NOT NULL
, project_id TEXT NOT NULL DEFAULT 'default');

CREATE TABLE bots (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  webhook_url TEXT,
  created_at TEXT NOT NULL
, handle TEXT, provider TEXT, model TEXT, capabilities TEXT, config TEXT, system_prompt TEXT, context_fetch_url TEXT, tool_execute_url TEXT, tools_schema TEXT, rate_limit_rpm INTEGER DEFAULT 60);

CREATE TABLE bridge_channel_mappings (
  id TEXT PRIMARY KEY,
  bridge_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  fluxychat_room_id TEXT NOT NULL,
  external_channel_id TEXT NOT NULL,
  external_channel_name TEXT,
  sync_direction TEXT NOT NULL DEFAULT 'both' CHECK (sync_direction IN ('inbound', 'outbound', 'both')),
  sync_reactions INTEGER NOT NULL DEFAULT 1,
  sync_attachments INTEGER NOT NULL DEFAULT 1,
  auto_reply INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);

CREATE TABLE bridge_configs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  platform TEXT NOT NULL CHECK (platform IN ('slack', 'discord')),
  name TEXT NOT NULL,
  token TEXT,
  webhook_url TEXT,
  bot_user_id TEXT,
  bot_display_name TEXT,
  status TEXT NOT NULL DEFAULT 'disconnected' CHECK (status IN ('connected', 'disconnected', 'error', 'rate_limited')),
  settings TEXT,
  last_sync_at TEXT,
  error_message TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE bridge_events (
  id TEXT PRIMARY KEY,
  bridge_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('message_sync', 'reaction_sync', 'attachment_sync', 'member_sync', 'channel_sync', 'error', 'connect', 'disconnect')),
  direction TEXT CHECK (direction IN ('inbound', 'outbound')),
  payload TEXT,
  status TEXT NOT NULL DEFAULT 'success' CHECK (status IN ('success', 'failed', 'skipped')),
  recorded_at TEXT NOT NULL
);

CREATE TABLE bridge_message_map (
  id TEXT PRIMARY KEY,
  bridge_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  fluxychat_message_id TEXT NOT NULL,
  external_message_id TEXT NOT NULL,
  external_platform TEXT NOT NULL,
  external_channel_id TEXT NOT NULL,
  direction TEXT NOT NULL CHECK (direction IN ('inbound', 'outbound')),
  synced_at TEXT NOT NULL
);

CREATE TABLE broadcast_campaigns (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  segment_id TEXT,
  name TEXT NOT NULL,
  message_template TEXT NOT NULL,
  channel TEXT NOT NULL DEFAULT 'in_app',
  status TEXT NOT NULL DEFAULT 'draft',
  scheduled_at TEXT,
  sent_at TEXT,
  total_recipients INTEGER NOT NULL DEFAULT 0,
  delivered INTEGER NOT NULL DEFAULT 0,
  failed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (segment_id) REFERENCES broadcast_segments(id)
);

CREATE TABLE broadcast_deliveries (
  id TEXT PRIMARY KEY,
  campaign_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  channel TEXT NOT NULL DEFAULT 'in_app',
  status TEXT NOT NULL DEFAULT 'pending',
  sent_at TEXT,
  delivered_at TEXT,
  read_at TEXT,
  error TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (campaign_id) REFERENCES broadcast_campaigns(id)
);

CREATE TABLE broadcast_segments (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  segment_type TEXT NOT NULL DEFAULT 'dynamic',
  rules TEXT NOT NULL DEFAULT '[]',
  user_count INTEGER NOT NULL DEFAULT 0,
  last_computed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE builtin_agent_templates (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  handle TEXT NOT NULL UNIQUE,
  provider TEXT NOT NULL DEFAULT 'openai',
  model TEXT NOT NULL DEFAULT 'gpt-4o-mini',
  system_prompt TEXT NOT NULL,
  capabilities TEXT NOT NULL DEFAULT 'chat',
  tools_schema TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE business_object_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  object_id TEXT NOT NULL,
  event_type TEXT NOT NULL,
  payload_json TEXT,
  actor_user_id TEXT,
  version INTEGER NOT NULL,
  created_at TEXT NOT NULL
);

CREATE TABLE business_object_subscriptions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  object_type TEXT,
  event_types_json TEXT,
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL
);

CREATE TABLE business_objects (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  object_type TEXT NOT NULL,
  object_id TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'active',
  payload_json TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  created_by TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE call_events (
  id TEXT PRIMARY KEY,
  call_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('join', 'leave', 'mute', 'unmute', 'video_on', 'video_off', 'screen_share_start', 'screen_share_stop', 'recording_start', 'recording_stop', 'quality_change')),
  user_id TEXT,
  metadata TEXT,
  recorded_at TEXT NOT NULL
);

CREATE TABLE call_participants (
  id TEXT PRIMARY KEY,
  call_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  display_name TEXT,
  joined_at TEXT NOT NULL,
  left_at TEXT,
  duration_ms INTEGER,
  audio_enabled INTEGER NOT NULL DEFAULT 1,
  video_enabled INTEGER NOT NULL DEFAULT 1,
  screen_sharing INTEGER NOT NULL DEFAULT 0,
  role TEXT DEFAULT 'participant' CHECK (role IN ('host', 'moderator', 'participant')),
  created_at TEXT NOT NULL
);

CREATE TABLE call_sessions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  provider TEXT NOT NULL DEFAULT 'livekit' CHECK (provider IN ('livekit', 'daily', 'custom')),
  provider_room_id TEXT,
  status TEXT NOT NULL DEFAULT 'waiting' CHECK (status IN ('waiting', 'active', 'ended')),
  started_by TEXT,
  started_at TEXT,
  ended_at TEXT,
  duration_ms INTEGER,
  recording_enabled INTEGER NOT NULL DEFAULT 0,
  recording_url TEXT,
  max_participants INTEGER DEFAULT 50,
  settings TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE channel_configs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  channel_type TEXT NOT NULL CHECK (channel_type IN ('chat', 'email', 'sms', 'whatsapp', 'telegram', 'slack', 'discord', 'webhook', 'custom')),
  channel_name TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1,
  settings TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE channel_routing_rules (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  channel_config_id TEXT NOT NULL,
  rule_name TEXT NOT NULL,
  match_pattern TEXT,
  target_room_id TEXT,
  target_room_pattern TEXT,
  priority INTEGER NOT NULL DEFAULT 0,
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (channel_config_id) REFERENCES channel_configs(id)
);

CREATE TABLE channel_thread_links (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  channel_type TEXT NOT NULL,
  external_thread_id TEXT NOT NULL,
  external_user_id TEXT,
  external_user_name TEXT,
  linked_at TEXT NOT NULL
);

CREATE TABLE cobrowsing_annotations (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('cursor', 'draw', 'text', 'highlight', 'arrow', 'rectangle', 'pointer')),
  payload TEXT NOT NULL,
  page_url TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE cobrowsing_sessions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  created_by TEXT NOT NULL,
  url TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'ended')),
  max_viewers INTEGER DEFAULT 25,
  annotations_enabled INTEGER NOT NULL DEFAULT 1,
  remote_control_enabled INTEGER NOT NULL DEFAULT 0,
  started_at TEXT NOT NULL,
  ended_at TEXT,
  duration_ms INTEGER,
  created_at TEXT NOT NULL
);

CREATE TABLE cobrowsing_viewers (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  display_name TEXT,
  joined_at TEXT NOT NULL,
  left_at TEXT,
  cursor_x REAL,
  cursor_y REAL,
  page_url TEXT,
  remote_control INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);

CREATE TABLE community_reputation (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  score INTEGER NOT NULL DEFAULT 0,
  level INTEGER NOT NULL DEFAULT 1,
  trusted INTEGER NOT NULL DEFAULT 0,
  warnings INTEGER NOT NULL DEFAULT 0,
  mutes INTEGER NOT NULL DEFAULT 0,
  last_active_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE companion_conversation_participants (
