  title TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'ended', 'handoff')),
  conversation_type TEXT NOT NULL DEFAULT 'group' CHECK (conversation_type IN ('group', 'pair', 'broadcast')),
  created_at TEXT NOT NULL,
  ended_at TEXT
);

