  reason TEXT,
  context TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'rejected', 'expired')),
  created_at TEXT NOT NULL,
  resolved_at TEXT
);

CREATE TABLE companion_emotion_state (
  id TEXT PRIMARY KEY,
