  room_id TEXT,
  retention_days INTEGER NOT NULL DEFAULT 90,
  auto_purge INTEGER NOT NULL DEFAULT 0,
  archive_before_delete INTEGER NOT NULL DEFAULT 0,
  archive_bucket TEXT,
