, parent_id INTEGER, edited_at TEXT, deleted_at TEXT, project_id TEXT NOT NULL DEFAULT 'default', mentions TEXT, og_title TEXT, og_description TEXT, og_image TEXT, og_url TEXT, client_message_id TEXT, expires_at TEXT, visibility TEXT, visible_to_json TEXT, kind TEXT NOT NULL DEFAULT 'text', duration_ms INTEGER, audio_url TEXT, transcription TEXT, transcription_status TEXT);

