  updated_at TEXT NOT NULL,
  created_at TEXT NOT NULL, stripe_customer_id TEXT, stripe_subscription_id TEXT, manually_overridden INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
);

CREATE TABLE project_secrets (
