  timestamp TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE "replay_mode_snapshots" (
  id TEXT PRIMARY KEY,
