  title TEXT NOT NULL,
  description TEXT,
  file_url TEXT,
  file_hash TEXT,
  collected_by TEXT,
  collected_at TEXT NOT NULL,
  expires_at TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE soc2_incidents (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  severity TEXT NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'investigating', 'contained', 'resolved', 'closed')),
  detected_at TEXT NOT NULL,
  reported_by TEXT,
  assigned_to TEXT,
  resolved_at TEXT,
  root_cause TEXT,
  remediation TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE soc2_policies (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  policy_type TEXT NOT NULL CHECK (policy_type IN ('security', 'acceptable_use', 'data_handling', 'incident_response', 'access_control', 'change_management', 'backup_recovery', 'vendor_management')),
  version TEXT NOT NULL DEFAULT '1.0',
  content TEXT,
  effective_date TEXT,
  review_date TEXT,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'archived', 'under_review')),
  owner TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE soc2_policy_acknowledgments (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  policy_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  acknowledged_at TEXT NOT NULL,
