);

CREATE TABLE soc2_reports (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  report_type TEXT NOT NULL CHECK (report_type IN ('compliance', 'risk', 'incident', 'audit', 'readiness')),
  title TEXT NOT NULL,
  content TEXT,
  generated_by TEXT,
  period_start TEXT,
  period_end TEXT,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'final', 'archived')),
  created_at TEXT NOT NULL
);

CREATE TABLE soc2_risk_assessments (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  risk_level TEXT NOT NULL CHECK (risk_level IN ('low', 'medium', 'high', 'critical')),
  likelihood TEXT NOT NULL CHECK (likelihood IN ('unlikely', 'possible', 'likely', 'almost_certain')),
  impact TEXT NOT NULL CHECK (impact IN ('negligible', 'minor', 'moderate', 'major', 'catastrophic')),
  mitigation TEXT,
  residual_risk TEXT,
  owner TEXT,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'mitigated', 'accepted', 'closed')),
  identified_at TEXT NOT NULL,
  reviewed_at TEXT,
  closed_at TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE streaming_overlays (
  id TEXT PRIMARY KEY,
