CREATE TRIGGER messages_fts_ad AFTER DELETE ON messages BEGIN INSERT INTO messages_fts(messages_fts, rowid, content) VALUES ('delete', old.id, coalesce(old.content, '')); END;

CREATE TRIGGER messages_fts_ai AFTER INSERT ON messages BEGIN INSERT INTO messages_fts(rowid, content) VALUES (new.id, coalesce(new.content, '')); END;

CREATE TRIGGER messages_fts_au AFTER UPDATE OF content, deleted_at ON messages BEGIN INSERT INTO messages_fts(messages_fts, rowid, content) VALUES ('delete', old.id, coalesce(old.content, '')); INSERT INTO messages_fts(rowid, content) SELECT new.id, coalesce(new.content, '') WHERE new.deleted_at IS NULL; END;
